.radio-options {
  display: flex;
  flex-direction: column;
  gap: 0.625rem;
}

.radio-label {
  display: flex;
  align-items: center;
  gap: 0.875rem;
  padding: 0.875rem 1rem;
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-md);
  cursor: pointer;
  transition:
    border-color var(--transition),
    background var(--transition),
    box-shadow var(--transition);
  user-select: none;
}

.radio-label:hover {
  border-color: var(--color-primary);
  background: #f0f2ff;
}

/* Hide the native radio visually; keep it in the a11y tree */
.radio-input {
  appearance: none;
  -webkit-appearance: none;
  width: 1.25rem;
  height: 1.25rem;
  min-width: 1.25rem;
  border: 2px solid var(--color-border);
  border-radius: 50%;
  background: var(--color-surface);
  transition:
    border-color var(--transition),
    background var(--transition);
  cursor: pointer;
  position: relative;
