  position: absolute;
  inset: 3px;
  border-radius: 50%;
  background: var(--color-radio-mark);
  transform: scale(0);
  transition: transform var(--transition);
}

.radio-input:checked {
  border-color: var(--color-primary);
  background: var(--color-primary);
