.radio-input:checked + .radio-label-text {
  font-weight: 600;
}

.radio-label:has(.radio-input:checked) {
  border-color: var(--color-primary);
  background: #f0f2ff;
  box-shadow: 0 0 0 1px var(--color-primary);
}

.radio-label-text {
  font-size: 0.9375rem;
  color: var(--color-text);
  transition: font-weight var(--transition);
}

.radio-icon {
  font-size: 1.1rem;
  flex-shrink: 0;
}

/* ── Required legend ──────────────────────────────────────────────── */
.required-note {
  font-size: 0.8125rem;
  color: var(--color-text-muted);
  margin-top: 1.5rem;
  margin-bottom: -0.5rem;
}
.required-note .required-marker { color: var(--color-error); }

/* ── Error message ────────────────────────────────────────────────── */
.field-error {
  display: none;
  font-size: 0.875rem;
  color: var(--color-error);
  margin-top: 0.5rem;
  font-weight: 500;
}

.field-error[aria-hidden="false"] {
  display: block;
