/* ── Status / confirmation message ───────────────────────────────── */
.status-message {
  display: none;
  padding: 1rem 1.25rem;
  border-radius: var(--radius-md);
  font-size: 0.9375rem;
  font-weight: 500;
  margin-top: 1.25rem;
}

.status-message--success {
