function PageHeader() {
  return `
    <header class="page-header">
      <span class="page-header__brand">Acme App</span>
    </header>
  `;
}

function RadioOption({ id, name, value, label, icon }) {
  return `
    <label class="radio-label" for="${id}">
      <input
        class="radio-input"
        type="radio"
        id="${id}"
        name="${name}"
        value="${value}"
        required
        aria-describedby="notification-error"
      />
      <span class="radio-icon" aria-hidden="true">${icon}</span>
      <span class="radio-label-text">${label}</span>
    </label>
  `;
}

function RadioGroup({ name, legendText, options }) {
  const optionsHTML = options
    .map((opt) => RadioOption({ name, ...opt }))
    .join("");

  return `
    <fieldset aria-describedby="notification-error">
      <legend>
        ${legendText}
        <span class="required-marker" aria-hidden="true"> *</span>
      </legend>
      <div class="radio-options">
        ${optionsHTML}
      </div>
      <p class="field-error" id="notification-error" role="alert" aria-hidden="true">
        Error: Please select a notification preference to continue.
      </p>
    </fieldset>
  `;
}

function NotificationForm() {
  const options = [
    { id: "notif-email",  value: "email", label: "Email",              icon: "✉️" },
    { id: "notif-sms",    value: "sms",   label: "SMS",                icon: "💬" },
    { id: "notif-push",   value: "push",  label: "Push Notifications", icon: "🔔" },
  ];

  return `
    <form id="notification-form" novalidate>
      <div class="form-field">
        ${RadioGroup({
          name: "notification-preference",
          legendText: "How do you prefer to receive notifications?",
          options,
        })}
      </div>

      <p class="required-note">
        Fields marked <span class="required-marker" aria-hidden="true">*</span>
        <span class="visually-hidden">with an asterisk</span> are required.
      </p>

      <button class="btn-submit" type="submit">Save preferences</button>

      <div
        class="status-message status-message--success"
        id="form-status"
        aria-live="polite"
        aria-hidden="true"
      ></div>
    </form>
  `;
}

function App() {
  return `
    ${PageHeader()}
    <main id="main" tabindex="-1">
      <div class="card" role="region" aria-label="Notification preferences">
        <p class="card__eyebrow">Settings</p>
