function PageHeader() {
  return `
    <header class="page-header">
      <span class="page-header__brand">Acme App</span>
    </header>
  `;
}

function RadioOption({ id, name, value, label, icon }) {
  return `
    <label class="radio-label" for="${id}">
      <input
        class="radio-input"
        type="radio"
        id="${id}"
        name="${name}"
        value="${value}"
        required
      />
      <span class="radio-icon" aria-hidden="true">${icon}</span>
      <span class="radio-label-text">${label}</span>
    </label>
  `;
}

function RadioGroup({ name, legendText, options }) {
  const optionsHTML = options
    .map((opt) => RadioOption({ name, ...opt }))
    .join("");

  return `
    <fieldset aria-describedby="notification-error">
      <legend>
        ${legendText}
        <span class="required-marker" aria-hidden="true"> *</span>
      </legend>
      <div class="radio-options">
        ${optionsHTML}
      </div>
      <p class="field-error" id="notification-error" role="alert" aria-hidden="true">
        Error: Please select a notification preference to continue.
      </p>
    </fieldset>
  `;
}

function NotificationForm() {
  const options = [
    { id: "notif-email",  value: "email", label: "Email",              icon: "✉️" },
    { id: "notif-sms",    value: "sms",   label: "SMS",                icon: "💬" },
    { id: "notif-push",   value: "push",  label: "Push Notifications", icon: "🔔" },
  ];

  return `
    <form id="notification-form" novalidate>
      <div class="form-field">
        ${RadioGroup({
          name: "notification-preference",
          legendText: "How do you prefer to receive notifications?",
          options,
        })}
      </div>

      <p class="required-note">
        Fields marked <span class="required-marker" aria-hidden="true">*</span>
        <span class="visually-hidden">with an asterisk</span> are required.
      </p>

      <button class="btn-submit" type="submit">Save preferences</button>

      <div
        class="status-message status-message--success"
        id="form-status"
        aria-live="polite"
        aria-hidden="true"
      ></div>
    </form>
  `;
}

function App() {
  return `
    ${PageHeader()}
    <main id="main" tabindex="-1">
      <div class="card" role="region" aria-label="Notification preferences">
        <p class="card__eyebrow">Settings</p>
        <h1 class="card__title">Notification preferences</h1>
        <p class="card__subtitle">
          Choose how you'd like us to reach you. You can update this at any time.
        </p>
        ${NotificationForm()}
      </div>
    </main>
  `;
}

// ── Mount ─────────────────────────────────────────────────────────────
document.getElementById("root").innerHTML = App();

// ── Form interaction ──────────────────────────────────────────────────
(function () {
  const form   = document.getElementById("notification-form");
  const error  = document.getElementById("notification-error");
  const status = document.getElementById("form-status");

  function showError() {
    error.setAttribute("aria-hidden", "false");
    // Focus the first radio so users can immediately make a selection
    const firstRadio = form.querySelector('input[type="radio"]');
    if (firstRadio) firstRadio.focus();
  }

  function clearError() {
    error.setAttribute("aria-hidden", "true");
  }

  // Clear error as soon as a selection is made
  form.addEventListener("change", (e) => {
    if (e.target.name === "notification-preference") clearError();
  });

  form.addEventListener("submit", (e) => {
    e.preventDefault();

    const selected = form.querySelector(
      'input[name="notification-preference"]:checked'
    );

    if (!selected) {
      showError();
      return;
    }

    clearError();

    const labels = {
      email: "Email",
      sms:   "SMS",
      push:  "Push Notifications",
    };

    status.textContent = `✓ Preference saved! You'll receive notifications via ${
      labels[selected.value]
    }.`;
    status.setAttribute("aria-hidden", "false");

    // Scroll status into view for small screens
    status.scrollIntoView({ behavior: "smooth", block: "nearest" });
  });
})();
