  const fmt = v => ({
    id: v.id,
    impact: v.impact,
    description: v.description,
    targets: v.nodes.map(n => n.target),
    html: v.nodes.map(n => n.html),
  });

  const out = { wcag: wcag.map(fmt), bp: bp.map(fmt) };
  process.stdout.write(JSON.stringify(out, null, 2) + "\n");
  process.exit(wcag.length > 0 ? 1 : 0);
})();
EOF
